from __future__ import annotations
import math, random, sys, time
sys.path.insert(0, "training")
from pipeline.training_metrics import CheckpointGate, SELECTION_Z

DEV = {
    "base64": (180, 157, 0), "collections": (180, 169, 157), "enum": (180, 174, 174),
    "heapq": (180, 162, 151), "statistics": (144, 137, 137), "textwrap": (180, 159, 159),
    "unicodedata": (180, 165, 41),
}
CONTROL = {"base64", "unicodedata"}
K = 4

def beta(rng, mean, kappa):
    if mean <= 0 or mean >= 1:
        return min(1.0, max(0.0, mean))
    return rng.betavariate(mean * kappa, (1 - mean) * kappa)

def latents(rng, kappa):
    out = {}
    for f, (n, c, nn) in DEV.items():
        out[f] = [(beta(rng, c / n, kappa), beta(rng, nn / c, kappa)) for _ in range(n // K)]
    return out

def draw(rng, lat, lift_c=0.0, lift_n=0.0):
    out = {}
    for f, cases in lat.items():
        rows = []
        for pc, q in cases:
            pn = pc * q
            pc2 = min(1.0, pc + lift_c)
            pn2 = min(pc2, pn + (lift_n if f not in CONTROL else 0.0))
            q2 = pn2 / pc2 if pc2 else 0.0
            cc = nc = 0
            for _ in range(K):
                if rng.random() < pc2:
                    cc += 1
                    if rng.random() < q2:
                        nc += 1
            rows.append((K, cc, nc))
        out[f] = rows
    return out

def metrics_of(counts):
    def fam(f):
        d = sum(x[0] for x in counts[f]); return (sum(x[1] for x in counts[f]) / d, sum(x[2] for x in counts[f]) / d, d)
    per = {f: fam(f) for f in counts}
    def over(keys, clusters):
        s = {"correct": sum(per[k][0] for k in keys) / len(keys),
             "correct_native": sum(per[k][1] for k in keys) / len(keys),
             "draws": sum(per[k][2] for k in keys)}
        if clusters:
            s["case_clusters"] = {"digest": ",".join(sorted(keys)), "families": [
                {"draws": [x[0] for x in counts[k]], "correct": [x[1] for x in counts[k]],
                 "native": [x[2] for x in counts[k]]} for k in sorted(keys)]}
        return s
    cov = [k for k in counts if k not in CONTROL]; ctl = [k for k in counts if k in CONTROL]
    return dict(over(list(counts), False), by_population={"coverage": over(cov, True), "fallback-control": over(ctl, True)}), per

def old_rule(bm, bper, cm):
    se = math.sqrt(sum(p[1] * (1 - p[1]) / p[2] for p in bper.values())) / len(bper)
    return cm["correct_native"] >= bm["correct_native"] + SELECTION_Z * se and cm["correct"] >= bm["correct"] - 0.02

def run(kappa, lift_c, lift_n, trials, seed=7, shared=True):
    rng = random.Random(seed)
    new = old = 0
    for _ in range(trials):
        lat = latents(rng, kappa)
        bm, bper = metrics_of(draw(rng, lat))
        clat = lat if shared else latents(rng, kappa)
        cm, _ = metrics_of(draw(rng, clat, lift_c, lift_n))
        g = CheckpointGate(baseline=bm); g.observe(25, cm)
        new += g.best_step == 25
        old += old_rule(bm, bper, cm)
    return new / trials, old / trials

if __name__ == "__main__":
    for kappa in (float(a) for a in sys.argv[1:]):
        t = time.time()
        print(kappa, "null", run(kappa, 0, 0, 4000), "n10", run(kappa, 0, .10, 4000), "both", run(kappa, .05, .10, 4000), "%.1fs" % (time.time() - t))

